"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["94739"],{223(e){e.exports=JSON.parse('{"id":78,"title":"\u65E0","description":"import os.path\\\\nimport sqlite3\\\\nimport tkinter as tk\\\\nimport cv2\\\\nimport numpy as np\\\\n\\\\nimport os\\\\n\\\\n# \u989C\u8272\u76F4\u65B9\u56FE\u7279\u5F81\u63D0\u53D6\u51FD\u6570\\\\ndef color_histogram_features(image):\\\\n    # \u5C06\u56FE\u50CF\u8F6C\u6362\u4E3A RGB \u989C\u8272\u7A7A\u95F4\\\\n    hsv = cv2.cvtColor(image, cv2.COLOR_BGR2HSV)\\\\n    # \u83B7\u53D6 HSV \u56FE\u50CF\u7684\u7B2C 0 \u4E2A\u548C\u7B2C 1 \u4E2A\u901A\u9053\\\\n    channels = [0, 1]\\\\n    # \u5EFA\u7ACB\u5728 HSV \u989C\u8272\u7A7A\u95F4\u4E2D Hue \u7684\u53D6\u503C\u8303\u56F4\u4E3A 0~180, Saturation \u7684\u53D6\u503C\u8303\u56F4\u4E3A 0~256\\\\n    hist_size = [180, 256]\\\\n    # Hue \u7684\u53D6\u503C\u8303\u56F4\u4E3A 0~180\\\\n    hue_range = [0, 180]\\\\n    # Saturation \u7684\u53D6\u503C\u8303\u56F4\u4E3A 0~256\\\\n    saturation_range = [0, 256]\\\\n    # \u6309\u7167\u524D\u9762\u5B9A\u4E49\u7684\u53C2\u6570\u8BA1\u7B97 HSV \u56FE\u50CF\u7684\u76F4\u65B9\u56FE\\\\n    hist = cv2.calcHist([hsv], channels, None, hist_size, [hue_range, saturation_range])\\\\n    # \u5BF9\u5F97\u5230\u7684\u76F4\u65B9\u56FE\u8FDB\u884C\u5F52\u4E00\u5316\u5904\u7406\\\\n    cv2.normalize(hist, hist)\\\\n    # \u8FD4\u56DE\u76F4\u65B9\u56FE\\\\n    return hist.flatten()\\\\n\\\\nBASE_DIR = os.path.dirname(os.path.abspath(__file__))\\\\ndb_path = os.path.join(BASE_DIR, \\\\\\"database.db\\\\\\")\\\\nconnect = sqlite3.connect(db_path)\\\\n\\\\n# \u521B\u5EFA\u6570\u636E\u5E93\u8FDE\u63A5\\\\ndef create_database_connection():\\\\n    conn = sqlite3.connect(\\\\\'database.db\\\\\')\\\\n    conn.execute(\\\\\\"CREATE TABLE IF NOT EXISTS images (id INTEGER PRIMARY KEY, image TEXT, features TEXT)\\\\\\")\\\\n    return conn\\\\n\\\\n# \u521B\u5EFA\u6570\u636E\u5E93\u8868\\\\ndef create_database_table(conn):\\\\n    conn.execute(\\\\\\"CREATE TABLE IF NOT EXISTS images (id INTEGER PRIMARY KEY, image TEXT, features TEXT)\\\\\\")\\\\n\\\\n# \u8FDE\u63A5\u6570\u636E\u5E93\u5E76\u67E5\u8BE2\u6570\u636E\\\\ndef connect_database(conn):\\\\n    cursor = conn.execute(\\\\\\"SELECT image, features FROM images\\\\\\")\\\\n    result = cursor.fetchall()\\\\n    return result\\\\n\\\\n# \u5C06\u6570\u636E\u96C6\u4E2D\u7684\u56FE\u50CF\u7279\u5F81\u5411\u91CF\u5B58\u50A8\u5230\u6570\u636E\u5E93\u4E2D\\\\ndef store_database(conn, images):\\\\n    for image, feature in images:\\\\n        cursor = conn.execute(\\\\\\"REPLACE INTO images (image, features) VALUES (?, ?)\\\\\\", (image, feature))\\\\n        conn.commit()\\\\n\\\\n# \u67E5\u8BE2\u6570\u636E\u5E93\u4E2D\u6240\u6709\u56FE\u50CF\u7684\u7279\u5F81\u5411\u91CF\\\\ndef query_database(conn):\\\\n    cursor = conn.execute(\\\\\\"SELECT features FROM images\\\\\\")\\\\n    result = cursor.fetchall()\\\\n    return result\\\\n\\\\nfrom tkinter import filedialog\\\\n\\\\ndef create_GUI_interface(conn):\\\\n    root = tk.Tk()\\\\n    root.title(\\\\\\"\u56FE\u50CF\u68C0\u7D22\u7CFB\u7EDF\\\\\\")\\\\n    root.geometry(\\\\\\"400x300\\\\\\")\\\\n\\\\n    label1 = tk.Label(root, text=\\\\\\"\u9009\u62E9\u56FE\u50CF\u6587\u4EF6\u5939\uFF1A\\\\\\")\\\\n    label1.pack()\\\\n\\\\n    input_box = tk.Entry(root)\\\\n    input_box.pack()\\\\n\\\\n    def browse_path():\\\\n        folder_path = filedialog.askdirectory()\\\\n        input_box.delete(0, tk.END)\\\\n        input_box.insert(0, folder_path)\\\\n\\\\n    browse_button = tk.Button(root, text=\\\\\\"\u6D4F\u89C8\\\\\\", command=browse_path)\\\\n    browse_button.pack()\\\\n\\\\n    label2 = tk.Label(root, text=\\\\\\"\u9009\u62E9\u76EE\u6807\u56FE\u50CF\uFF1A\\\\\\")\\\\n    label2.pack()\\\\n\\\\n    def select_target_image():\\\\n        target_image_path = filedialog.askopenfilename(title=\\\\\\"\u9009\u62E9\u76EE\u6807\u56FE\u50CF\\\\\\")\\\\n        target_box.delete(0, tk.END)\\\\n        target_box.insert(0, target_image_path)\\\\n\\\\n    target_button = tk.Button(root, text=\\\\\\"\u9009\u62E9\u76EE\u6807\u56FE\u50CF\\\\\\", command=select_target_image)\\\\n    target_button.pack()\\\\n\\\\n    target_box = tk.Entry(root)\\\\n    target_box.pack()\\\\n\\\\n    def get_similar_images():\\\\n        target_image_path = target_box.get()\\\\n        folder_path = input_box.get()\\\\n\\\\n        # \u52A0\u8F7D\u76EE\u6807\u56FE\u50CF\\\\n        target_image = cv2.imread(target_image_path)\\\\n\\\\n        # \u8BA1\u7B97\u76EE\u6807\u56FE\u50CF\u7684\u989C\u8272\u7279\u5F81\\\\n        target_features = color_histogram_features(target_image)\\\\n\\\\n        # \u5C06\u56FE\u50CF\u6587\u4EF6\u5939\u4E2D\u7684\u6240\u6709\u56FE\u50CF\u548C\u5176\u7279\u5F81\u5411\u91CF\u6DFB\u52A0\u5230\u6570\u636E\u5E93\u4E2D\\\\n        add_images_to_database(folder_path, conn)\\\\n\\\\n        # \u8FDE\u63A5\u5230\u7279\u5F81\u6570\u636E\u5E93\u5E76\u67E5\u8BE2\u6240\u6709\u56FE\u50CF\u7684\u989C\u8272\u7279\u5F81\\\\n        all_features = connect_database(conn)\\\\n\\\\n        # \u8BA1\u7B97\u76EE\u6807\u56FE\u50CF\u4E0E\u6240\u6709\u56FE\u50CF\u7684\u6B27\u5F0F\u8DDD\u79BB\\\\n        distances = []\\\\n        for image, feature in all_features:\\\\n            feature = np.fromstring(feature, dtype=float, sep=\\\\\' \\\\\')\\\\n            distance = cv2.compareHist(target_features, feature, cv2.HISTCMP_CHISQR)\\\\n            distances.append((image, distance))\\\\n\\\\n        # \u6839\u636E\u6B27\u5F0F\u8DDD\u79BB\u7684\u5927\u5C0F\u5BF9\u6240\u6709\u56FE\u50CF\u8FDB\u884C\u6392\u5E8F\uFF0C\u5E76\u8FD4\u56DE\u6700\u76F8\u4F3C\u7684\u524D\u4E94\u5F20\u56FE\u50CF\\\\n        distances.sort(key=lambda x: x[1])\\\\n        similar_images = distances[:5]\\\\n\\\\n        # \u8F93\u51FA\u7ED3\u679C\u5230\u63A7\u5236\u53F0\\\\n        for image, distance in similar_images:\\\\n            print(f\\\\\\"Image {image} is {distance} away from the target image.\\\\\\")\\\\n\\\\n    submit_button = tk.Button(root, text=\\\\\\"\u67E5\u8BE2\\\\\\", command=get_similar_images)\\\\n    submit_button.pack()\\\\n\\\\n    close_button = tk.Button(root, text=\\\\\\"\u5173\u95ED\\\\\\", command=root.quit)\\\\n    close_button.pack()\\\\n\\\\n    message = tk.Message(root, text=\\\\\\"\u989C\u8272\u7279\u5F81\u4FE1\u606F\u5DF2\u50A8\u5B58\u5230\u6570\u636E\u5E93\u4E2D\uFF01\\\\\\")\\\\n    message.pack()\\\\n\\\\n    root.mainloop()\\\\n\\\\n\\\\ndef add_images_to_database(folder_path, conn):\\\\n    for root, dirs, files in os.walk(folder_path):\\\\n        for file_name in files:\\\\n            file_path = os.path.join(root, file_name)\\\\n            image = cv2.imread(file_path)\\\\n            features = color_histogram_features(image)\\\\n            conn.execute(\\\\\\"REPLACE INTO images (image, features) VALUES (?, ?)\\\\\\", (file_path, np.array2string(features)))\\\\n            conn.commit()\\\\n\\\\ncreate_GUI_interface(connect)\\\\nconnect.close()\u5C06\u989C\u8272\u63D0\u53D6\u4E2D\u9009\u62E9\u7684\u4E24\u4E2A\u901A\u9053\u6539\u4E3A\u4E09\u901A\u9053\uFF0C\u4FEE\u6539\u540E\uFF0C\u8F93\u51FA\u5B8C\u6574\u7CFB\u7EDF\u4EE3\u7801","remark":"Contributed by GUN","owner":"GUN","upvotes":4,"downvotes":0,"upvoteDifference":4,"updatedAt":"2026-04-13T20:38:09.394Z"}')}}]);